import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"RFC 0093 — Device-only tier: key custody and data-loss recovery, native and web","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0093-device-only-storage-and-key-custody.md"},"headers":[],"relativePath":"rfcs/0093-device-only-storage-and-key-custody.md","filePath":"rfcs/0093-device-only-storage-and-key-custody.md"}'),n={name:"rfcs/0093-device-only-storage-and-key-custody.md"};function s(r,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="rfc-0093-—-device-only-tier-key-custody-and-data-loss-recovery-native-and-web" tabindex="-1">RFC 0093 — Device-only tier: key custody and data-loss recovery, native and web <a class="header-anchor" href="#rfc-0093-—-device-only-tier-key-custody-and-data-loss-recovery-native-and-web" aria-label="Permalink to &quot;RFC 0093 — Device-only tier: key custody and data-loss recovery, native and web&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> August 2026<br><strong>Author:</strong> kasunben (design session with Claude Code)<br><strong>Scope:</strong> <code>packages/bridge</code> (new Capacitor secure-storage transport), <code>packages/sdk</code> (device-client capability surface, WebAuthn PRF helpers, <code>sdk.offline</code>&#39;s native/OPFS backends), <code>packages/manifest</code> (new <code>device:secureStorage</code> permission), <code>apps/auth</code> (PRF enrollment on the existing passkey flow), <code>runtime</code> (Console operator toggle, <code>.env</code> gate), <code>plugins/account</code> (enrollment/recovery UX), <code>docs/architecture-rules.md</code>, <code>docs/plugin-development.md</code>. Resolves research <a href="./../research/0012-offline-first-architecture.html">0012</a>&#39;s Open Questions 1 (escrow) and 3 (key strictness) and elaborates its <code>device-only</code> key-custody recommendation into a concrete design covering <strong>both</strong> native shells and plain web/PWA. Builds on RFC <a href="./0083-device-bridge-capability-contract.html">0083</a> (device bridge — adds a <code>secureStorage</code> capability to that contract) and reuses RFC <a href="./0060-client-side-encryption-core.html">0060</a>&#39;s (client-side encryption core) recovery-secret and wrapped-key server-storage machinery for the opt-in backup path. Directly informs epic tasks 8.21, 20.13, 8.20, 1.22 (workstream 0008 leg 4).<br><strong>Incorporated into plan:</strong> Yes — unblocks workstream 0008 leg 4, which was gated on exactly the decision this RFC makes.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Defines how a <code>device-only</code> plugin&#39;s data is actually stored and protected — on a native shell (Capacitor) <strong>and</strong> on plain web/PWA — and what happens when the key that protects it dies. Five decisions, previously open:</p><ol><li><strong>Storage backend.</strong> Native: SQLite, SQLCipher-encrypted, app-sandboxed — built directly against the SQLCipher native libraries, not the <code>@capacitor-community/sqlite</code> plugin originally named here; see &quot;Resolved in v0.7&quot; below for why. Web: OPFS + <code>wa-sqlite</code> (<code>OPFSCoopSyncVFS</code>), with <code>navigator.storage.persist()</code> requested at setup. Neither is IndexedDB, and the reason is the same on both: IndexedDB is evictable everywhere it was tested (research 0008).</li><li><strong>Key custody.</strong> Native: Keychain (iOS) / Keystore (Android). Web: WebAuthn PRF, building on the passkey infrastructure already deployed (<code>apps/auth/src/auth.ts:231</code>). Both release the key only via a live biometric/passcode (or platform-authenticator) prompt each time — never a JS-side &quot;unlocked&quot; flag — and <strong>both must accept a device passcode as a fallback, never biometric-only</strong> (see section 5 — this corrects an error in this RFC&#39;s own first draft).</li><li><strong>One Device Storage Key, set up once, shared by every plugin.</strong> Account → Security gets a new &quot;Device Storage Key&quot; section, parallel to RFC 0060&#39;s existing &quot;Client-side encryption&quot; section — same UX pattern, cryptographically independent secret, and a deliberately distinct name from RFC 0060&#39;s own existing (unrelated) internal &quot;device key&quot; concept (<code>e2ee-device.ts</code> — see &quot;Current state&quot;). Not triggered per-plugin; a plugin that finds it missing directs the user there rather than running its own enrollment.</li><li><strong>Surviving key invalidation short of device loss.</strong> A second, independent recovery wrapper on the same underlying key, so a deleted passkey or an OS-level credential change doesn&#39;t destroy data by itself — only losing the device does.</li><li><strong>Escrow.</strong> A three-layer, progressively-available recovery model, platform-agnostic, for the one failure mode the second wrapper can&#39;t cover: the device itself being lost, stolen, or wiped.</li></ol><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Research 0012 established that <code>device-only</code>&#39;s entire reason to exist is durable, encrypted, presence-gated local storage — and that IndexedDB satisfies none of that on iOS, nor does it have a presence gate anywhere. It also identified, without resolving, that a hardware-bound key is invalidated by design under three circumstances (biometric re-enrollment, passkey deletion, device loss), and left the resulting data-loss question as its one deliberately unresolved open question: <em>&quot;This is a product decision about what Sovereign promises... it should be made explicitly before any RFC commits to a design.&quot;</em> It separately left key strictness (<code>biometryCurrentSet</code> vs. <code>userPresence</code>) as an open tradeoff, despite its own text a few paragraphs earlier already ruling one of them out on accessibility grounds.</p><p>Both decisions have now been made (design session, August 2026), for native <strong>and</strong> web, plus concrete mechanisms to implement them against. This RFC records all of it so tasks 20.13 and 1.22 (leg 4, previously blocked) have something to build.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li><code>packages/sdk/src/offline.ts</code> — the existing plugin-scoped KV cache. Its doc comment explicitly scopes it &quot;Browser-only&quot;; it opens <code>indexedDB.open(&#39;sovereign-offline&#39;, 1)</code> unconditionally (<code>offline.ts:96-108</code>). This is the <code>offline-first</code>-tier mechanism and is <strong>not</strong> in scope for this RFC — it stays IndexedDB-backed everywhere.</li><li><code>packages/sdk/src/e2ee-device.ts</code> — RFC 0060&#39;s existing &quot;Device Key&quot; mechanism. Also IndexedDB-backed (<code>DB_NAME = &#39;sovereign-e2ee&#39;</code>, <code>e2ee-device.ts:13-29</code>), and the stored <code>CryptoKey</code>, while non-extractable, is released to any script on the origin with no presence check (<code>getDeviceKey()</code>, <code>e2ee-device.ts:53-63</code>). Confirmed during this design session to be <strong>insufficient as the <code>device-only</code> primary key</strong> for two independent reasons: it inherits IndexedDB&#39;s eviction risk, and it has no live-auth gate. Its recovery-secret machinery remains a good fit for a <em>different</em> piece — see section 4.</li><li><code>packages/sdk/src/device-client.ts:124-126</code> — <code>isDeviceOnlyTierAvailable()</code> already exists, gated on <code>supports(&#39;secureStorage&#39;)</code>, and already returns <code>false</code> everywhere pending exactly the bridge capability this RFC&#39;s design informs.</li><li><code>apps/auth/src/auth.ts:231</code> — better-auth&#39;s <code>passkey()</code> plugin is already configured and live. WebAuthn is deployed today; PRF is an extension on top of infrastructure that already exists, not a new subsystem.</li><li>RFC 0083 defines the device bridge capability contract generally (<code>haptics</code>, <code>notifications</code>, etc.); this RFC&#39;s native design is a new capability (<code>secureStorage</code>) on that same contract, not a new mechanism.</li><li>RFC 0060 (<code>e2ee-crypto.ts</code>/<code>e2ee-object.ts</code>/<code>e2ee-device.ts</code>) already implements a Client Master Key wrapped by a user-held recovery secret, with the wrapped (ciphertext) CMK stored server-side and a documented Account UX for setup, unlock, and recovery-secret handling. Its threat model and recovery shape (server holds ciphertext it cannot read; a recovery secret unwraps it) is exactly the shape this RFC&#39;s opt-in escrow layer needs — reused, not reinvented.</li><li>Epic task 1.22 (<code>docs/epics/users-auth.md:974-1011</code>) already specifies &quot;Web/PWA: WebAuthn PRF key derivation... Native: key stored via task 20.13&#39;s <code>device:secureStorage</code> bridge, with user-presence access control (biometric <strong>or</strong> device passcode — never biometric-only)&quot; and was gated on task 8.21 (the escrow decision) until this RFC resolved it. This RFC&#39;s design is that task&#39;s own scope, made concrete — not new scope invented here.</li><li>Workstream 0008 leg 4 (<code>docs/workstreams/0008-offline-first-architecture.md</code>) was marked a workstream <strong>gate</strong> while this decision was open, and already named <code>@capacitor-community/sqlite</code> (SQLCipher) as the native storage pick and <code>secureStorage</code> as the permission name. This RFC&#39;s acceptance lifts that gate — see the workstream doc&#39;s own changelog.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="_1-storage-backend" tabindex="-1">1. Storage backend <a class="header-anchor" href="#_1-storage-backend" aria-label="Permalink to &quot;1. Storage backend&quot;">​</a></h3><p><strong>Native (Capacitor):</strong> a SQLCipher-encrypted SQLite database, one database per instance (not per plugin — mirrors <code>sdk.offline</code>&#39;s existing shared-database, composite-key-per-plugin shape, so the storage layer&#39;s schema and isolation model don&#39;t have to be reinvented, only its backend swapped). Lives in the app&#39;s sandboxed storage — outside <code>WKWebsiteDataStore</code> on iOS, so it is not subject to the storage-pressure/non-interaction eviction policy IndexedDB is. <strong>Not</strong> reached via <code>@capacitor-community/sqlite</code> as originally named here — see &quot;Resolved in v0.7&quot; under Open questions: that plugin&#39;s entire API is JS-facing and unreachable from this shell&#39;s bridge -isolated remote content, so <code>sovereign-mobile</code> links the same underlying native SQLCipher libraries directly instead.</p><p><strong>Web/PWA:</strong> OPFS via <code>wa-sqlite</code>&#39;s <code>OPFSCoopSyncVFS</code> — research 0012&#39;s own &quot;2026 production pick for the web,&quot; chosen specifically because it does <strong>not</strong> require COOP/COEP headers (the official <code>sqlite-wasm</code> OPFS build does, and those headers would fight this platform&#39;s CSP). At <code>device-only</code> enrollment, the browser is asked for <code>navigator.storage.persist()</code>. This is a request, not a guarantee — see &quot;What web cannot fully match,&quot; below.</p><p>Both backends are reached through the same plugin-facing shape (this RFC does not redesign that surface — see task 3.37, &quot;Unified offline storage SDK surface,&quot; already scoped separately). <code>isDeviceOnlyTierAvailable()</code> (<code>device-client.ts</code>) checks both independently — a native <code>secureStorage</code>-capable transport, or web/PWA&#39;s own WebAuthn PRF + OPFS support — and is <code>true</code> if either is present. A plugin declaring <code>device-only</code> on a surface with neither sees <code>isDeviceOnlyTierAvailable() === false</code> and the existing capability-restricted UI treatment (research 0012, shipped in leg 3) applies — no manifest change, no plugin-visible branching.</p><p><strong>Interim key/value primitive, stated plainly:</strong> <code>device-only-kv.ts</code> implements a smaller piece of this today, across both backends — not the <code>wa-sqlite</code> relational engine described above (a plugin needing actual SQL, joins, indices, or cross-record queries is not served by it), but durable, encrypted, per-record storage with no query needs, which is the more common case. Each function (<code>get</code>/<code>set</code>/<code>delete</code>/<code>list</code>/<code>clear</code>) checks <code>supports(&#39;secureStorage&#39;)</code> first: <strong>native</strong> routes straight through the bridge&#39;s <code>secureStorage</code> capability — <code>sovereign-mobile</code>&#39;s SQLCipher database is already the encryption boundary, so no second, app-level encryption layer runs on this path; <strong>web/PWA</strong> falls through to the AES-GCM-encrypted-over-OPFS implementation (one file per key, per plugin) using the unlocked Device Storage Key from <code>device-only-session.ts</code>, as originally shipped. One exception: <code>listDeviceOnlyPluginIds()</code> (enumerate every plugin with <code>device-only</code> data, not a single plugin&#39;s own keys) stayed OPFS-only — the <code>secureStorage</code> wire protocol has no &quot;list all plugin ids&quot; operation, only per-plugin-scoped ones, and its only caller (<code>device-only-export.ts</code>&#39;s full export/import, RFC 0093 §4 Layer 2) is itself web-only for the same reason, so the gap is already masked in practice. See <code>docs/plugin-development.md</code>&#39;s <code>device-only</code> tier section for the plugin-facing API, and <code>example-plugins/example-device-only</code> for a plugin exercising both backends end to end, including its own transport-specific gating (see &quot;Resolved in v0.7 (continued)&quot; under Open questions).</p><h3 id="_2-primary-key-custody" tabindex="-1">2. Primary key custody <a class="header-anchor" href="#_2-primary-key-custody" aria-label="Permalink to &quot;2. Primary key custody&quot;">​</a></h3><p><strong>Native:</strong> the SQLCipher database key (a 256-bit symmetric key) is generated on-device and held in:</p><ul><li><strong>iOS:</strong> Keychain, with <code>kSecAccessControlUserPresence</code>.</li><li><strong>Android:</strong> Keystore, with <code>setUserAuthenticationRequired(true)</code> (device credential enabled as an accepted authenticator type, not biometric-only).</li></ul><p>Release requires a live biometric-<strong>or</strong>-passcode prompt, subject to the re-lock policy below. Implemented as a new <code>secureStorage</code> capability in <code>@sovereignfs/bridge</code>&#39;s Capacitor transport, calling through a thin custom bridge written directly against <code>LocalAuthentication</code>/<code>BiometricPrompt</code> + Keychain/Keystore — see &quot;Resolved in v0.6&quot; under Open questions for why no third-party plugin was adopted. <code>sdk.device.*</code> never talks to Keychain/Keystore directly; it calls the bridge capability, matching every other native capability in RFC 0083&#39;s contract.</p><p>Android Keystore keys are non-extractable by design — there is no route to the raw key bytes this section describes for iOS&#39;s Keychain. <code>sovereign-mobile</code> resolves this with envelope encryption: a <code>SecureRandom</code>-generated database key is wrapped by an authentication-gated Keystore AES key and the ciphertext lives in <code>SharedPreferences</code>, unwrapped via <code>Cipher.init()</code> on every use — still authentication-gated, so the property this section actually requires (release of the key is gated) holds identically; only the storage mechanics differ. See that repo&#39;s own <code>docs/epics/bridge.md</code> task 20.13 entry for the full implementation detail on both platforms.</p><p><strong>Web/PWA:</strong> WebAuthn&#39;s PRF extension, via <code>navigator.credentials.get()</code> against the user&#39;s existing passkey. If the existing credential doesn&#39;t support PRF, the enrollment flow registers a <strong>new</strong> passkey with the extension explicitly requested — it does not assume the login passkey can be reused (matching task 1.22&#39;s own note). The derived output is used directly as (or to derive, via HKDF) the OPFS database&#39;s encryption key. Same property as native: the secret backing it never leaves the platform authenticator (frequently the same Secure Enclave/StrongBox chip Keychain/ Keystore use), and it can only be reproduced by repeating the ceremony — live proof, every time.</p><p><strong>Where and when setup happens (resolved): centralized in Account → Security, once, decoupled from any single plugin.</strong> Not triggered inline the first time a user opens <em>some</em> <code>device-only</code> plugin. Account → Security gets a new <strong>&quot;Device Storage Key&quot;</strong> section, alongside the existing &quot;Client-side encryption&quot; (RFC 0060) section — same UX pattern (setup, recovery-secret display, settings), same location, but a cryptographically <strong>independent</strong> secret from RFC 0060&#39;s CMK (see section 3 — considered and deliberately rejected sharing the two), and a deliberately distinct name from RFC 0060&#39;s own existing, unrelated internal &quot;device key&quot; concept (<code>e2ee-device.ts</code>). Set up once, the resulting key is shared by <strong>every</strong><code>device-only</code> plugin the user has or later gets access to — not one key per plugin, matching the storage model in section 1, which was already one database per instance, never one per plugin.</p><p>A <code>device-only</code> plugin that finds no Device Storage Key set up does not run its own enrollment ceremony inline — it shows a message directing the user to Account → Security and stops there. This is a deliberate decoupling from plugin access: a plugin&#39;s install/access-policy lifecycle (who can open it at all — an entirely separate, existing mechanism, RFC 0065) has nothing to do with whether that user&#39;s Device Storage Key exists yet. Revoking and later re-granting a user&#39;s access to a plugin does not touch their Device Storage Key or its data either way — the two lifecycles don&#39;t interact.</p><p><strong>PRF salt and versioning (resolved).</strong> A single fixed salt constant, scoped to exactly this purpose and derived from a descriptive string (e.g. <code>sha256(&quot;sovereign:device-only-storage:v1&quot;)</code>, not a hand-picked hex literal, so it stays auditable) — never a per-user or random salt; the salt&#39;s only job is domain separation between different <em>purposes</em> using the same passkey, not between users, and the credential&#39;s own hardware secret already supplies the actual security. This matters concretely if RFC 0060&#39;s own CMK ever adopts PRF unlock too: a different, equally fixed salt for that purpose guarantees the two derived keys are cryptographically independent, so a compromise of one context can never imply the other. A version tag travels with the wrapped-key ciphertext, matching RFC 0060&#39;s own &quot;explicit algorithm/version metadata stored with each encrypted object&quot; convention, so a future scheme change doesn&#39;t strand already- enrolled users.</p><p><strong>Re-lock policy (resolved): timed, by default, with a user override.</strong> Neither &quot;per launch&quot; nor &quot;every open&quot; alone, and the choice is sharpened by a finding from this platform&#39;s own WKWebView testing (research 0008/ 0012, epic task 20.10): iOS discards the entire JS execution context on backgrounding — a fresh reload every time the app returns to foreground — while Android WebView preserves it. That means &quot;unlock once per launch&quot; is <strong>already, accidentally, &quot;unlock every open&quot; on iOS</strong> (free security from a platform quirk) but genuinely <strong>&quot;unlock once, stay unlocked indefinitely while backgrounded&quot;</strong> on Android, with nothing forcing re-authentication. Same nominal policy, two different real guarantees per platform — not an acceptable place to leave an implicit inconsistency. Default: re-lock after a timed window of the app being backgrounded (or immediately on backgrounding — the exact duration is an implementation detail, not a design question), applied deliberately on <strong>both</strong> platforms rather than relying on iOS&#39;s behavior to cover for a policy that doesn&#39;t actually specify it. User-adjustable in Account settings — stricter (immediate) to more lenient (a longer window) — matching research 0012&#39;s own &quot;default plus a user override&quot; framing. Applies identically to native and web.</p><p>On web, the preference (<code>device-only-storage.ts</code>&#39;s <code>saveReLockPolicy</code>/ <code>loadReLockPolicy</code>) and its enforcement are deliberately separate modules: <code>device-only-session.ts</code>&#39;s <code>getUnlockedDeviceStorageKey()</code> holds the unwrapped key in memory only for the caller&#39;s process lifetime, comparing elapsed wall-clock time against the chosen window on each access rather than relying on a timer to fire while backgrounded (browsers throttle or suspend those unreliably) — see that module&#39;s own doc comment for the full reasoning, including why a discarded JS context (iOS&#39;s behavior above) self-enforces even more strictly than the policy requires rather than needing separate handling. On native, the equivalent enforcement is Keychain/Keystore&#39;s own access-control window (<code>SecureStorage.swift</code>&#39;s <code>reuseWindow</code>/<code>sovereign-mobile</code>&#39;s <code>SecureStorage.java</code> key-validity duration) — see task 20.13.</p><p><strong>Explicitly rejected: a JS-side PIN or &quot;unlocked&quot; flag as the gate, on either platform.</strong> A PIN that merely sets a boolean in app state is bypassed entirely by reading raw storage — the check is never in an attacker&#39;s path. A PIN that actually wraps the key (ciphertext-at-rest, not a flag) is stronger but has no hardware-enforced rate limiting: an attacker who extracts the database can brute-force a human-length PIN offline, unlimited attempts, no lockout. Only a hardware-backed access-control primitive (Keychain/Keystore, or WebAuthn&#39;s platform authenticator on web) closes that gap. Any future proposal to add a PIN-only fallback for convenience should cite this section rather than re-litigate it from scratch.</p><p><strong>Explicitly rejected: plain WebAuthn (no PRF) as a client-side gate.</strong> A plain WebAuthn assertion is a signed yes/no proof meant for a relying party to verify — it does not itself hand back usable key material. Gating a local decrypt on &quot;did the assertion succeed&quot; while the actual key sits statically in local storage is the same theater problem as the JS-flag case above: an attacker reading raw storage never has to pass the check. PRF is what makes the ceremony produce something actually usable as a key.</p><h3 id="_3-surviving-key-invalidation-short-of-device-loss" tabindex="-1">3. Surviving key invalidation short of device loss <a class="header-anchor" href="#_3-surviving-key-invalidation-short-of-device-loss" aria-label="Permalink to &quot;3. Surviving key invalidation short of device loss&quot;">​</a></h3><p>A hardware-bound key can stop working without the device being lost: a passkey gets deleted (web), an OS credential change invalidates a Keychain/Keystore item in ways that vary by exact configuration and OS version, or (independent of the <code>userPresence</code>-equivalent choice in section 5 surviving <em>most</em> biometric re-enrollments) some platform combination doesn&#39;t. Without a second path, any of these destroys <code>device-only</code> data even though the device itself is still in the user&#39;s hands — clearly unacceptable for the passkey-deletion case, which is a hard, unconditional break with no &quot;survives it&quot; equivalent.</p><p>Standard key-slot design (the same shape LUKS and FileVault use) solves this cheaply on both platforms: the actual database key is wrapped <strong>twice</strong>, independently:</p><ul><li><strong>Wrapper 1 (daily use):</strong> the Keychain/Keystore or WebAuthn-PRF key, as above.</li><li><strong>Wrapper 2 (recovery):</strong> a recovery secret, reusing RFC 0060&#39;s <em>existing</em> recovery-secret generation, display, and re-entry UX (<code>plugins/account/app/_components/EncryptionSection.tsx</code> and <code>e2ee-crypto.ts</code>&#39;s wrap/unwrap primitives) rather than building parallel cryptographic machinery. <strong>Resolved: this is a separate, independent secret from RFC 0060&#39;s own CMK recovery secret — not the same one.</strong> Enabling a <code>device-only</code> plugin never requires touching e2ee setup, and a breach of one recovery secret does not expose data protected by the other. This does cost a user who adopts both features a second phrase to keep track of; that cost is accepted deliberately rather than merging the two systems&#39; blast radius for the sake of one shared secret being marginally easier to manage than two — the entire reason <code>device-only</code> is its own tier, distinct from <code>offline-first</code>, is to keep a class of especially sensitive data walled off, and a shared recovery secret would quietly undo part of that separation. The recovery secret is shown once, when the Device Storage Key is set up in Account → Security (see section 2&#39;s &quot;Where and when setup happens&quot;), and the user is told to save it, exactly as RFC 0060 already does for its own CMK — same UX pattern, different secret, different section of the same page.</li></ul><p>Both wrappers protect the <em>same</em> underlying database key — two independent doors to one room, not two copies of the data. When wrapper 1 stops working (passkey deleted, Keychain/Keystore item invalidated), the app detects this and prompts for the recovery secret to re-derive the key via wrapper 2; once unlocked, a fresh wrapper 1 is generated and the recovery secret isn&#39;t needed again until the next such event. No data is re-encrypted or moved — only the key&#39;s wrapping changes.</p><p>This does <strong>not</strong> resolve &quot;device lost or wiped&quot; — if the recovery secret only ever existed on that same device (memorized, or written down and also lost), losing the device loses both wrappers together. That is what the escrow layer below is for.</p><h3 id="_4-escrow-recovering-from-device-loss" tabindex="-1">4. Escrow: recovering from device loss <a class="header-anchor" href="#_4-escrow-recovering-from-device-loss" aria-label="Permalink to &quot;4. Escrow: recovering from device loss&quot;">​</a></h3><p>Three layers, available progressively, platform-agnostic:</p><p><strong>Layer 1 — mandatory, always shown.</strong> At <code>device-only</code> enrollment, before any data is committed, a plain-language warning: what device-only means, that losing the device with no recovery secret saved means permanent, unrecoverable loss, stated as the tier&#39;s defining property, not an edge case buried in settings.</p><p><strong>Layer 2 — always available, no toggle.</strong> User-driven export: an encrypted file (never plaintext) the user can generate on demand and re-generate after changes, importable to restore on a new device. No server involvement at all — this exists regardless of the toggle in Layer 3, and answers device-to-device migration for a user who doesn&#39;t want any server-side footprint whatsoever.</p><p>Implemented as <code>device-only-export.ts</code>&#39;s <code>exportDeviceOnlyData</code>/ <code>importDeviceOnlyData</code> — a full snapshot of every plugin&#39;s <code>device-only-kv.ts</code> data in one encrypted file per call, wrapped under a user-chosen passphrase with the same PBKDF2/AES-GCM shape section 3&#39;s recovery-secret wrapper uses (a different passphrase and a different purpose, not the same secret). Import re-encrypts each value under the <em>importing</em> device&#39;s own unlocked Device Storage Key rather than copying ciphertext across devices — the exporting and importing devices&#39; keys are never the same secret. See <code>docs/plugin-development.md</code>&#39;s <code>device-only</code> tier section for the plugin-facing note (plugin authors don&#39;t call this themselves; Account → Security&#39;s export/import action does).</p><p><strong>Layer 3 — opt-in, three-gate cascade.</strong> Encrypted server backup, reusing RFC 0060&#39;s wrapped-key server-storage pattern (the server stores ciphertext of the recovery-wrapped key; it never receives the key or the recovery secret in the clear). Available only when all three gates are open:</p><ol><li><strong><code>.env</code></strong> — an instance-level flag the operator must set before the capability exists at all for that instance (the hard kill switch, consistent with how other sensitive opt-in features are gated in this codebase).</li><li><strong>Console</strong> — once the env allows it, <code>platform:owner</code>/<code>platform:admin</code> decides whether this instance offers it, at all, to any user.</li><li><strong>Per-plugin, per-user opt-in</strong> — even with both gates open, each user decides per <code>device-only</code> plugin whether that plugin&#39;s data gets backed up.</li></ol><p>With no env flag set (the default), an instance behaves exactly as if Layer 3 didn&#39;t exist — Layers 1 and 2 are unconditional and unaffected.</p><h3 id="_5-key-strictness-userpresence-equivalent-required-one-setting-for-everyone" tabindex="-1">5. Key strictness: <code>userPresence</code>-equivalent, required, one setting for everyone <a class="header-anchor" href="#_5-key-strictness-userpresence-equivalent-required-one-setting-for-everyone" aria-label="Permalink to &quot;5. Key strictness: `userPresence`-equivalent, required, one setting for everyone&quot;">​</a></h3><p><strong>Correction from this RFC&#39;s first draft.</strong> That draft specified <code>kSecAccessControlBiometryCurrentSet</code> (biometric-only, invalidated on any enrollment change) as the native access-control flag. That is wrong and is corrected here: research 0012 itself already states, a few sections before its own &quot;open question&quot; framing of this exact tradeoff, <em>&quot;Call it device auth, not biometric: both platforms allow biometric or device passcode against the same hardware-backed key... Biometric-only would lock out every user who has not enrolled a face or finger.&quot;</em> Epic task 1.22 already specifies the same requirement independently. Treating this as an open tradeoff in the first draft was an error, not a reconsideration of settled guidance — this RFC now matches what was already decided elsewhere.</p><p><strong>Decision: <code>kSecAccessControlUserPresence</code> (iOS) / <code>setUserAuthenticationRequired(true)</code> with device-credential fallback enabled (Android) / whatever a given browser&#39;s platform authenticator accepts as an equivalent (web, via PRF) — for every <code>device-only</code> plugin, not manifest-declared per plugin.</strong> A single, well-understood, accessible setting is simpler to document and support than per-plugin variance, and this is no longer really a tradeoff between two viable options: only the <code>userPresence</code>-equivalent choice satisfies the accessibility requirement that was never actually up for debate. Section 3&#39;s second wrapper remains valuable regardless — it is what makes passkey deletion (web) and any OS-level credential-invalidation edge case (native) survivable — but it is no longer the thing that makes the <em>primary</em> flag&#39;s strictness acceptable, because the primary flag is no longer strict.</p><h3 id="_6-what-web-cannot-fully-match" tabindex="-1">6. What web cannot fully match <a class="header-anchor" href="#_6-what-web-cannot-fully-match" aria-label="Permalink to &quot;6. What web cannot fully match&quot;">​</a></h3><p>Stated plainly rather than implied: WebAuthn PRF gets the <strong>key-custody</strong> half to a genuinely equal bar as native — same class of hardware backing, same live-proof-required-every-time property, same hardware-enforced brute-force resistance. It does not get the <strong>storage-durability</strong> half to an equal bar. <code>navigator.storage.persist()</code> is a request the browser may deny, based on its own heuristics, and even granted it does not carry an OS app sandbox&#39;s guarantee — a user&#39;s &quot;clear site data&quot; action, or a browser&#39;s own data-clearing settings, can still remove it in ways an installed native app&#39;s storage is not exposed to. If <code>persist()</code> is denied at enrollment, the user is told plainly, in the same spirit as the Layer 1 escrow warning — not silently degraded to a weaker guarantee with no notice. <code>device-only</code> on web is real and hardware-backed for the key; it is best-effort, not guaranteed, for the data surviving to be unlocked at all.</p><h3 id="_7-revocation-position" tabindex="-1">7. Revocation position <a class="header-anchor" href="#_7-revocation-position" aria-label="Permalink to &quot;7. Revocation position&quot;">​</a></h3><p>Stated deliberately, per research 0012&#39;s open question 4: server-side account deactivation/purge does <strong>not</strong> and cannot reach <code>device-only</code> data — the server never holds a usable key, on either platform. For a sovereignty product this is the correct position (it is the user&#39;s data on the user&#39;s device), but it is a real departure from the existing sign-out purge&#39;s assumption that it reaches everything, and must be documented in <code>docs/architecture-rules.md</code> as a stated exception once implemented, not discovered later by an operator expecting deactivation to be total.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><p><strong>Derive the key from device + user credentials, server-assisted.</strong> Rejected. If the server can (by verifying credentials) derive or reconstruct the key, then anyone with access to the auth database can too — this silently converts <code>device-only</code> into <code>offline-first</code> with a misleading name. A version that preserves the &quot;server never learns the key&quot; property is possible via an OPRF-style blinded protocol, but that requires a rate-limited, tamper-resistant server-side component (ideally enclave-backed) purpose-built to resist offline brute-forcing of a human password — materially <em>more</em> infrastructure than Keychain/Keystore or PRF custody, not a simplification. Worth revisiting only if a future plugin needs <code>device-only</code>-grade guarantees for users with no platform authenticator at all.</p><p><strong>Reuse RFC 0060&#39;s existing Device Key as <code>device-only</code>&#39;s primary key.</strong> Rejected — see &quot;Current state&quot; above. IndexedDB-backed, no presence gate. Its recovery-secret and wrapped-key-storage <em>machinery</em> is reused (section 3, section 4 Layer 3); the key itself is not.</p><p><strong>PIN-only software wrapping, on either platform.</strong> Rejected — see section 2. No hardware rate limiting; brute-forceable offline once the storage is extracted. Worse on web than native, since web has no hardware fallback to lean on at all if the PIN wrapper is the only protection.</p><p><strong>Plain WebAuthn without PRF as a client-side gate.</strong> Rejected — see section 2. Produces a yes/no signal, not key material; gating a local decrypt on it is the same theater pattern as a JS-side flag.</p><p><strong><code>kSecAccessControlBiometryCurrentSet</code> (this RFC&#39;s own first draft).</strong> Rejected on reflection — see section 5. Locks out users without enrolled biometrics, contradicting an accessibility requirement already stated elsewhere in research 0012 and epic task 1.22.</p><p><strong>Operator escrow by default.</strong> Rejected, same reasoning RFC 0060 already established: the threat model this tier defends against includes a compromised operator, so an operator-held default recovery path contradicts the tier&#39;s own purpose. Operator involvement only ever enters via the explicit, opt-in, env-gated Layer 3 — and even there, the operator controls <em>whether the capability exists</em>, never the key itself.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p><strong>Resolved since v0.3</strong> (design session, August 2026) — PRF salt scheme, re-lock policy, and the RFC 0060 integration shape are no longer open; see section 2 (salt scheme, re-lock policy) and section 3 (recovery-secret independence) above for the decisions and reasoning. Kept here only as a changelog pointer, not restated.</p><p><strong>Resolved in v0.6</strong> (design review + developer confirmation, August 2026) — the Capacitor secure-storage implementation is a <strong>thin custom bridge</strong>, not a third-party plugin. A desk review of the readily available, maintained candidates found none that cleanly meet this section&#39;s requirement:</p><ul><li><strong><code>@aparajita/capacitor-secure-storage</code></strong> stores values encrypted at rest (Keychain / Keystore-backed AES-GCM) but applies <strong>no access control to the item itself</strong> — biometric gating is a separate, non-binding check via its companion <code>@aparajita/capacitor-biometric-auth</code> plugin, called before <code>get()</code>/<code>set()</code> in JS. That is exactly the &quot;JS-side PIN or &#39;unlocked&#39; flag as the gate&quot; pattern this section already rejects above: the storage item has no hardware-enforced lock of its own, so anything that can call the plugin&#39;s <code>get()</code> can read the value without passing through the biometric check at all.</li><li><strong><code>capacitor-secure-storage-plugin</code></strong> exposes no access-control parameters whatsoever — plain encrypted storage only.</li><li><strong><code>@drefrajo/capacitor-biometric-keychain</code></strong> does invoke device biometric authentication automatically on <code>getItem()</code>/<code>setItem()</code> (closer to the right shape), but its README documents no option to require a <strong>device-credential fallback</strong> rather than biometry alone, and — small project (single-digit-star range, two open issues at review time) — whether the underlying native binding is actually the hardware access-control primitive versus an app-level check ahead of a plain read isn&#39;t verifiable from its public docs.</li><li>Where the correct native pattern <em>does</em> appear in the wild (an <code>accessControl</code>/<code>SecAccessControlCreateFlags</code> value bound to the Keychain item on iOS, a <code>CryptoObject</code>-gated key on Android), the default nearly everyone reaches for is <code>.biometryCurrentSet</code>/<code>.biometryAny</code> — <strong>biometry-only</strong> — the exact configuration §5 below already corrected once in this RFC&#39;s own design (&quot;never biometric-only, which locks out unenrolled users&quot;). Any pre-built option would need explicit, verified confirmation that it supports the device-credential-inclusive variant (<code>.userPresence</code> on iOS, <code>setDeviceCredentialAllowed(true)</code> alongside <code>setUserAuthenticationRequired(true)</code> on Android), not just whichever flag its README happens to mention — none of the reviewed candidates offered that confirmation.</li></ul><p><strong>The decision:</strong> write the bridge directly against <code>LocalAuthentication</code>/ <code>BiometricPrompt</code> + Keychain/Keystore APIs, rather than adopt a third-party plugin. The native surface needed is small and fully specified by this section (one access-controlled item per device, <code>get</code>/<code>set</code>/<code>remove</code>/ <code>keys</code>/<code>clear</code>, <code>kSecAccessControlUserPresence</code> / <code>setUserAuthenticationRequired(true)</code> with device-credential enabled) — writing it directly avoids taking a dependency on a third-party plugin whose correctness on precisely this security property can&#39;t be verified from outside, for a surface too small to be worth that risk. <code>sovereign-mobile</code>&#39;s implementer should still re-check this bar against whatever the plugin ecosystem looks like at build time (a library closing this exact gap may exist by then) rather than treat &quot;write it from scratch&quot; as unconditional — but the bar stays &quot;verified to bind the device-credential-inclusive access-control flag to the item itself,&quot; not &quot;has a biometric prompt somewhere in its API.&quot;</p><p><strong>Resolved in v0.7</strong> (<code>sovereign-mobile</code> implementation, August 2026) — the storage-backend pick from section 1, <code>@capacitor-community/sqlite</code>, is unusable as this shell is built and was replaced with a direct SQLCipher library dependency, not evaluated against alternatives (there was no alternative-plugin question here — the finding ruled out the entire &quot;native storage via a Capacitor plugin&quot; approach, not just one plugin&#39;s choice of access-control flag as v0.6 did for key custody).</p><p>The problem: <code>@capacitor-community/sqlite</code>&#39;s entire API is JS-facing (<code>window.Capacitor</code> + registered-plugin calls from page JS), but this shell strips Capacitor&#39;s own bridge from the WebView whenever it shows remote content — <code>sovereign-mobile</code>&#39;s <code>MainViewController.swift</code> documents this as &quot;Bridge isolation,&quot; a hard security property of the shell (RFC 0080&#39;s device-surface model depends on the remote page never reaching raw Capacitor), not a bug to route around. The plugin has no native-to-native API to call instead; its Swift/Kotlin implementation is written to be driven by its own JS bridge glue, which is exactly what gets removed. This was confirmed by inspecting the plugin&#39;s own source (its podspec/<code>build.gradle</code> dependency declarations), not assumed.</p><p><strong>The fix:</strong> link the same underlying native SQLCipher libraries that plugin itself depends on, directly — <code>SQLCipher.swift</code> (the official Zetetic-maintained Swift Package) on iOS, <code>net.zetetic:sqlcipher-android</code> + <code>androidx.sqlite:sqlite</code> on Android — bypassing the plugin wrapper entirely. Both link and build-verify cleanly (real <code>xcodebuild</code>/<code>:app:assembleDebug</code> runs, not just dependency resolution) against <code>sovereign-mobile</code>&#39;s existing project structure. Full detail, including the resulting iOS/Android key-custody divergence this forced (Android Keystore&#39;s non-extractability, noted in section 2 above), lives in that repo&#39;s own <code>docs/epics/bridge.md</code> task 20.13 entry — not restated here since it&#39;s implementation detail this RFC&#39;s &quot;Native (Capacitor)&quot; line only needs to name correctly, not fully re-derive.</p><p>This is a correction to this RFC&#39;s own section 1, not a new decision this RFC needed to make: the <em>shape</em> section 1 specifies (a SQLCipher-encrypted SQLite database, app-sandboxed, one per instance) is unchanged and fully delivered — only the mechanism reaching it (direct library linkage instead of a Capacitor plugin) differs from what was originally named.</p><p><strong>Resolved in v0.7 (continued)</strong> — with the native <code>secureStorage</code> bridge capability build- and interactively-verified on both platforms (task 20.13), two plugin-facing gaps stood between that and an actually-usable <code>device-only</code> tier on native shells, both found and closed by live-testing against a real installed native app rather than trusting the earlier build-verification alone:</p><ol><li><code>plugins/account/app/_components/DeviceStorageKeySection.tsx</code> (the Account → Security setup UI) unconditionally called the web-only <code>getDeviceStorageKeyStatus()</code>, which always answers <code>&#39;unsupported&#39;</code> on native (it checks WebAuthn/OPFS availability, not the bridge) — making the entire section permanently unreachable there. Fixed with a transport-specific dispatcher: <code>supports(&#39;secureStorage&#39;)</code> picks between a native branch (no enrollment step — native has none, the OS gates every <code>secureStorage</code> call directly — just a &quot;Verify it works&quot; round-trip button surfacing the device&#39;s real state, including the <code>&#39;no-device-auth&#39;</code> hard block from section 5) and the original web/PWA setup flow, unchanged.</li><li><code>device-only-kv.ts</code> itself — the actual plugin-data storage primitive the fix above only gates access to — was still entirely OPFS-only, so even after fix 1, no <code>device-only</code> plugin could persist anything on a native shell; the read/write would silently no-op against a key derivation path (<code>getUnlockedDeviceStorageKey()</code>) that only ever returns <code>&#39;unsupported&#39;</code> there. Closed as described in section 1&#39;s &quot;Interim key/value primitive&quot; paragraph above: each of <code>get</code>/<code>set</code>/<code>delete</code>/<code>list</code>/<code>clear</code> now checks <code>supports(&#39;secureStorage&#39;)</code> and routes through the bridge on native, falling through to the original OPFS path otherwise.</li></ol><p>The reference plugin (<code>example-plugins/example-device-only</code>, <code>DeviceOnlyNotesView.tsx</code>) had the same class of bug as fix 1 — it gated its own content behind <code>getDeviceStorageKeyStatus()</code> unconditionally, so it would have stayed permanently blocked on native even with both fixes above in place. Given the same transport-specific treatment: on native it skips straight to its <code>NotesPanel</code> (no enrollment gate to pass), and hides the web-only unlock-session badge/&quot;Lock now&quot; control and the <code>ExportImportPanel</code> (RFC 0093 §4 Layer 2&#39;s export/import is web-only for the same <code>listDeviceOnlyPluginIds()</code> reason noted above) rather than presenting controls that would silently do nothing. Verified live on the iOS Simulator against a real installed native app, not just typechecked: created a note, confirmed it round-tripped through the bridge, force-killed and relaunched the app, and confirmed the note survived — proving the write path goes through the actual SQLCipher database rather than an in-memory cache that a fresh JS context would lose.</p><p>Still open:</p><ol><li><strong>Minimum browser/OS support floor for web <code>device-only</code>.</strong> PRF needs iOS 18/Safari 18+ and recent Chrome/Android; below that, <code>isDeviceOnlyTierAvailable()</code> correctly reports <code>false</code> and the capability-restricted UI applies, but the exact floor needs to be pinned and documented for plugin authors and Console&#39;s install-review surface.</li><li><strong>Tauri/desktop parity.</strong> Owned by <code>sovereign-desktop</code>&#39;s own task 17.4 / workstream 0003 leg 3b, not this RFC — noted here only so a reader doesn&#39;t assume desktop is silently included.</li></ol><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p>Unblocks workstream 0008 leg 4 (<code>docs/workstreams/0008-offline-first-architecture.md</code>), sequenced 8.21 → 20.13 → 8.20 → 1.22 per that workstream&#39;s existing plan. This RFC <em>is</em> the 8.21 decision, plus the key-custody design both 20.13 (native transport) and 1.22 (device-auth unlock, native and web) need; once accepted, leg 4 is no longer blocked on a product decision, only on implementation. The Capacitor transport (section 2, native half) is built in <code>sovereign-mobile</code> against the <code>@sovereignfs/bridge</code> contract this repo publishes, per the existing repo-split table in the workstream doc. The web half (PRF enrollment, OPFS backend) is this repo&#39;s own work under task 1.22 and does not depend on any other repository.</p><p>Manifest impact: none by itself (the <code>offline: &#39;device-only&#39;</code> enum value already shipped in leg 3). New <code>device:secureStorage</code> permission is part of task 20.13&#39;s own scope, not this RFC&#39;s.</p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.8</td><td>August 2026</td><td>Closed the gap between task 20.13&#39;s build-verified native <code>secureStorage</code> bridge and an actually-usable native <code>device-only</code> tier, found by live-testing against a real installed native app rather than trusting the build-verification alone: <code>DeviceStorageKeySection.tsx</code> and <code>device-only-kv.ts</code> both unconditionally used web-only status/key-derivation functions that always answer &quot;unsupported&quot; on native, permanently blocking the tier&#39;s UI and its data storage respectively. Both now dispatch on <code>supports(&#39;secureStorage&#39;)</code>; <code>device-only-kv.ts</code>&#39;s native path routes straight through the bridge with no app-level re-encryption layer (the SQLCipher database is already the encryption boundary), matching every function except <code>listDeviceOnlyPluginIds()</code> (no bridge equivalent exists, and its only caller is already web-only). The reference plugin (<code>example-plugins/example-device-only</code>) had the same gating bug and was fixed the same way. Verified live on the iOS Simulator: a note written through the reference plugin survived a force-kill and relaunch of the app. Section 1 and &quot;Resolved in v0.7&quot; under Open questions updated.</td></tr><tr><td>0.7</td><td>August 2026</td><td>Section 1&#39;s storage-backend pick corrected: <code>@capacitor-community/sqlite</code> is unusable in <code>sovereign-mobile</code> as built — its JS-facing API is unreachable from the remote page under this shell&#39;s bridge-isolation model. Replaced with a direct SQLCipher library dependency (<code>SQLCipher.swift</code> on iOS, <code>net.zetetic:sqlcipher-android</code> on Android), confirmed by inspecting the plugin&#39;s own source and build- and link-verified on both platforms. Section 2 updated to note Android Keystore&#39;s non-extractability forces envelope encryption there, unlike iOS&#39;s direct Keychain-held raw key. See &quot;Resolved in v0.7&quot; under Open questions.</td></tr><tr><td>0.6</td><td>August 2026</td><td>Open question 1 (Capacitor secure-storage plugin choice) resolved: a thin custom bridge, not a third-party plugin. None of the readily available candidates bind a device-credential-inclusive access-control flag to the storage item itself — <code>@aparajita/capacitor-secure-storage</code> gates biometry via a separate, non-binding companion check (the JS-side-gate pattern this RFC already rejects), <code>capacitor-secure-storage-plugin</code> has no access-control option at all, and <code>@drefrajo/capacitor-biometric-keychain</code>&#39;s binding mechanism isn&#39;t verifiable from its public docs. Confirmed by the developer; <code>sovereign-mobile</code> should still re-check the plugin landscape at build time against the stated bar, not treat this as unconditional, but the default is now build-it, not evaluate-first.</td></tr><tr><td>0.5</td><td>August 2026</td><td>Enrollment centralized: one &quot;Device Storage Key&quot; (renamed from &quot;Device Key&quot; to avoid colliding with RFC 0060&#39;s existing, unrelated internal &quot;device key&quot; concept), set up once in Account → Security (parallel to RFC 0060&#39;s Client-side encryption section, cryptographically independent from it), shared by every <code>device-only</code> plugin — not triggered per-plugin. A plugin missing it directs the user to Account → Security instead of running its own enrollment ceremony. Decouples Device Storage Key lifecycle from any plugin&#39;s access grant (RFC 0065) entirely. Section 2, section 3 wording updated to match.</td></tr><tr><td>0.4</td><td>August 2026</td><td>Resolved the three remaining open questions: PRF salt/versioning scheme (fixed purpose-scoped salt + version tag, section 2), re-lock policy (timed default with a user override, chosen specifically to close the iOS/Android backgrounding-behavior asymmetry task 20.10 found, section 2), and the RFC 0060 integration shape (device-only&#39;s recovery secret is independent of RFC 0060&#39;s CMK recovery secret, section 3).</td></tr><tr><td>0.3</td><td>August 2026</td><td>Accepted. Unblocks workstream 0008 leg 4 — see the workstream doc&#39;s own changelog for the leg-4 status update this triggered.</td></tr><tr><td>0.2</td><td>August 2026</td><td>Brought web/PWA into scope (was deferred in 0.1): WebAuthn PRF key custody, OPFS/<code>wa-sqlite</code> storage, <code>navigator.storage.persist()</code> handling. Corrected an error in 0.1 — replaced <code>kSecAccessControlBiometryCurrentSet</code> with a <code>userPresence</code>-equivalent flag everywhere, matching an accessibility requirement research 0012 and epic task 1.22 had already established; resolves research 0012&#39;s open question 3 as well as open question 1.</td></tr><tr><td>0.1</td><td>August 2026</td><td>Initial draft, from a design session resolving research 0012&#39;s escrow open question and elaborating its device-only key-custody recommendation. Native (Capacitor) only; web explicitly deferred.</td></tr></tbody></table>',77)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
